<script setup lang="ts">
/**
 * A donut chart showing part-to-whole shares at a glance (`design/components/donut-chart.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/donut-chart.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import {
  DEFAULT_CHART_MESSAGES,
  Icon,
  UNMEASURED,
  agentMember,
  chartMarks,
  chartPosition,
  chooseChartMark,
  createReading,
  createWarningLog,
  devWarning,
  donutChartModel,
  donutChartReadout,
  donutChartSelection,
  measureBox,
  readChartPosition,
  readingRest,
  readingView,
  useListening,
  type ChartMessages,
  type ChartTooltipConfig,
  type DonutCenter,
  type DonutSegment,
  type ValueFormat,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/charts/donut-chart.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button.vue'
import Table from '../structure/Table.vue'
import TableBody from '../structure/TableBody.vue'
import TableCell from '../structure/TableCell.vue'
import TableHead from '../structure/TableHead.vue'
import TableHeader from '../structure/TableHeader.vue'
import TableRow from '../structure/TableRow.vue'

export interface DonutChartProps {
  center?: DonutCenter
  /**
   * Formats segment values in the tooltip and the twin.
   */
  format?: ValueFormat
  label: string
  loading?: boolean
  locale?: string
  /**
   * The chart tier's string catalog (`ChartMessages`). Defaults to generic English; a localized
   * host passes the same object to every chart.
   */
  messages?: ChartMessages
  /**
   * The segments, at most 6. A seventh raises a dev warning suggesting an "Other" segment.
   */
  segments: readonly DonutSegment[]
  size?: 'sm' | 'md' | 'lg'
  tooltip?: false | ChartTooltipConfig
}

defineOptions({ name: 'DonutChart', inheritAttrs: false })

const props = withDefaults(defineProps<DonutChartProps>(), {
  loading: false,
  messages: () => DEFAULT_CHART_MESSAGES,
  size: 'md',
  tooltip: () => ({}),
})
const emit = defineEmits<{
  select: [selection: { key: string; label: string; value: number; share: number }]
}>()
const listening = useListening()
const box = ref(UNMEASURED)
const reading = ref(createReading({ count: 0, seriesStart: null }))
const position = ref(readingRest(null))
const twinOpen = ref(false)
const warningLog = ref(createWarningLog())
const frame = useTemplateRef<HTMLElement>('frame')
const plot = useTemplateRef<HTMLElement>('plot')
const input = computed(() => ({
  segments: props.segments,
  center: props.center,
  format: props.format,
  label: props.label,
  locale: props.locale,
  messages: props.messages,
  tooltip: props.tooltip,
  loading: props.loading,
  selectable: listening.select,
  box: box.value,
}))
const model = computed(() => donutChartModel(input.value))
const view = computed(() => readingView(position.value, props.segments.length))
const readout = computed(() => donutChartReadout(input.value, model.value, view.value))
const activate = computed(() => () => {
  const selection = donutChartSelection(input.value, model.value, reading.value.now())
  if (selection !== null) emit('select', selection)
})
const walk = computed(() => ({ count: props.segments.length }))
const marks = computed(() => ({
  walk: walk.value,
  input: input.value,
  model: model.value,
  readout: donutChartReadout,
  selection: donutChartSelection,
}))
const onKey = computed(() => (event: KeyboardEvent) => {
  if (listening.select && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault()
    activate.value()
    return
  }
  reading.value.update(walk.value)
  if (reading.value.key(event.key)) event.preventDefault()
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    box.value = plot.value === null ? box.value : measureBox(plot.value, box.value)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [plot.value]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
const effect2 = () => {
  reading.value.subscribe((now) => {
    position.value = now
  })
}
onMounted(effect2)
const effect3 = () => {
  warningLog.value.log(model.value.warnings, (message) => devWarning(true, message))
}
onMounted(effect3)
watch(() => model.value.warnings.join('\n'), effect3, { flush: 'post' })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = !listening.select
    ? () => {}
    : agentMember({
        member: 'DonutChart',
        element: () => frame.value,
        state: () => ({
          items: chartMarks(marks.value, reading.value),
          position: chartPosition(marks.value, reading.value),
          count: walk.value.count,
        }),
        actions: {
          read: {
            argument: 'number',
            run: (value) => readChartPosition(marks.value, value, reading.value),
          },
          choose: {
            argument: 'id',
            run: (value) => chooseChartMark(marks.value, value, reading.value, activate.value),
          },
        },
      })
  release4 = () => {
    ran()
  }
}
onMounted(effect4)
onBeforeUnmount(() => release4?.())
</script>

<template>
  <figure
    ref="frame"
    :class="chartFrame.frame"
    :data-size="size"
    :data-state="model.state"
    :data-position="view.active ? view.index : undefined"
    :aria-label="label"
    data-member="donut-chart"
  >
    <!-- region -->
    <div :class="chartFrame.region">
      <!-- y axis -->
      <div :class="chartFrame.yAxis" />
      <!-- plot -->
      <div ref="plot" :class="chartFrame.plot">
        <div v-if="model.state === 'empty'" :class="chartFrame.empty">
          <span>
            {{ messages.empty }}
          </span>
        </div>
        <!-- surface -->
        <div
          v-else
          :class="styles.surface"
          tabindex="0"
          role="img"
          :aria-label="label"
          @keydown="onKey($event)"
          @click="activate()"
          @pointerleave="reading.clear()"
          @blur="reading.clear()"
        >
          <!-- marks -->
          <svg
            v-if="model.plot !== null"
            :class="styles.marks"
            :data-reading="view.active ? '' : undefined"
            :width="model.plot?.width"
            :height="model.plot?.height"
            aria-hidden="true"
            focusable="false"
          >
            <!-- ring centre -->
            <g :transform="model.plot?.transform">
              <!-- ring -->
              <g>
                <template v-for="arc in model.plot?.arcs ?? []" :key="arc.key">
                  <path
                    :class="styles.segment"
                    :style="{ '--pm-chart-mark': arc.paint }"
                    :data-active="view.index === arc.index ? '' : undefined"
                    :d="arc.d"
                  />
                </template>
              </g>
              <!-- hits -->
              <g>
                <template v-for="arc in model.plot?.arcs ?? []" :key="arc.key">
                  <path
                    :class="styles.hit"
                    :d="arc.hit"
                    @pointerenter="reading.moveTo(arc.index)"
                  />
                </template>
              </g>
            </g>
            <!-- centre figure -->
            <g v-if="(model.plot?.center ?? null) !== null" :class="styles.center">
              <text :x="model.plot?.center?.x" :y="model.plot?.center?.y" text-anchor="middle">
                {{ model.plot?.center?.value }}
              </text>
              <text
                v-if="model.plot?.center?.label !== undefined"
                :class="styles.centerLabel"
                :x="model.plot?.center?.x"
                :y="model.plot?.center?.labelY"
                text-anchor="middle"
              >
                {{ model.plot?.center?.label }}
              </text>
            </g>
          </svg>
        </div>
        <!-- tooltip -->
        <div
          v-if="readout.tooltip !== null"
          :class="chartTooltip.tooltip"
          :style="{
            '--pm-chart-tip-x': `${readout.tooltip?.x}px`,
            '--pm-chart-tip-y': `${readout.tooltip?.y}px`,
          }"
          :data-indicator="readout.tooltip?.indicator"
          :data-side="readout.tooltip?.side"
          aria-hidden="true"
        >
          <p v-if="readout.tooltip?.header !== undefined" :class="chartTooltip.header">
            {{ readout.tooltip?.header }}
          </p>
          <ul :class="chartTooltip.rows">
            <template v-for="row in readout.tooltip?.rows ?? []" :key="row.key">
              <li :class="chartTooltip.row">
                <span :class="chartTooltip.key" :style="{ '--pm-chart-key': row.paint }" />
                <span :class="chartTooltip.value">
                  {{ row.value }}
                </span>
                <span :class="chartTooltip.label">
                  {{ row.label }}
                </span>
              </li>
            </template>
          </ul>
        </div>
      </div>
      <!-- x axis -->
      <div :class="chartFrame.xAxis" />
    </div>
    <template v-if="model.legend">
      <!-- legend -->
      <ul v-if="model.painted.length > 0" :class="chartLegend.legend" data-key-shape="rect">
        <template v-for="entry in model.painted" :key="entry.key">
          <li :class="chartLegend.item">
            <span
              :class="chartLegend.swatch"
              :style="{ '--pm-chart-key': entry.paint }"
              aria-hidden="true"
            />
            <span v-if="entry.icon !== undefined" :class="chartLegend.glyph">
              <Icon :name="entry.icon" size="sm" />
            </span>
            <span :class="chartLegend.label">
              {{ entry.label }}
            </span>
          </li>
        </template>
      </ul>
    </template>
    <!-- summary -->
    <span :class="a11y.visuallyHidden">
      {{ model.summary }}
    </span>
    <!-- twin -->
    <div :class="chartTwin.twin" :data-state="twinOpen ? 'open' : 'closed'">
      <div :class="chartTwin.toggle">
        <Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="table"
          :iconOnly="true"
          :label="twinOpen ? messages.hideTable(label) : messages.showTable(label)"
          @click="twinOpen = !twinOpen"
        />
      </div>
      <div v-if="twinOpen" :class="chartTwin.table">
        <Table :label="messages.tableLabel(label)" :caption="messages.tableLabel(label)">
          <TableHead>
            <TableRow>
              <template v-for="column in model.twin.columns" :key="column.key">
                <TableHeader :numeric="column.numeric">
                  {{ column.label }}
                </TableHeader>
              </template>
            </TableRow>
          </TableHead>
          <TableBody>
            <template v-for="(row, line) in model.twin.rows" :key="line">
              <TableRow>
                <template
                  v-for="(cell, cellIndex) in row"
                  :key="model.twin.columns[cellIndex]?.key ?? cellIndex"
                >
                  <TableCell :numeric="model.twin.columns[cellIndex]?.numeric">
                    {{ cell === '' ? '—' : cell }}
                  </TableCell>
                </template>
              </TableRow>
            </template>
          </TableBody>
        </Table>
      </div>
    </div>
    <!-- live region -->
    <span :class="a11y.visuallyHidden">
      <div aria-live="polite" aria-atomic="true">
        {{ readout.announcement }}
      </div>
    </span>
  </figure>
</template>
